import Link from 'next/link';
import { notFound } from 'next/navigation';
import { getApplicationById } from '@/lib/applications';

// PageProps is generated by Next from the folder path, so `id` is typed for us.
const ApplicationDetailPage = async (props: PageProps<'/applications/[id]'>) => {
    // `id` comes from the URL: /applications/2 → id = '2' (always a string).
    const { id } = await props.params;
    const application = getApplicationById(id);

    // Unknown id → render the 404 page and stop here (notFound() throws).
    if (!application) {
        notFound();
    }

    const fields: [string, string | null][] = [
        ['Status', application.status],
        ['Job URL', application.jobUrl],
        ['Applied', application.appliedAt?.toLocaleDateString() ?? null],
        ['Salary range', application.salaryRange],
        ['Recruiter', application.recruiterName],
        ['Email used', application.emailUsed],
        ['Work permit support', application.permitSupport],
        ['Notes', application.notes],
    ];

    return (
        <main className="mx-auto max-w-3xl p-6">
            <Link href="/applications" className="text-sm text-zinc-500 hover:underline">
                ← All applications
            </Link>
            <h1 className="mt-2 text-2xl font-semibold">{application.company}</h1>
            <p className="mb-6 text-zinc-500">{application.role}</p>

            <dl className="divide-y rounded border">
                {fields.map(([label, value]) => (
                    <div key={label} className="flex gap-4 p-4">
                        <dt className="w-48 shrink-0 text-sm text-zinc-500">{label}</dt>
                        <dd className="break-all">{value ?? '—'}</dd>
                    </div>
                ))}
            </dl>
        </main>
    );
}

export default ApplicationDetailPage;
